<script lang="ts">
	import type { PageData } from './$types';

	export let data: PageData;

	let svgElement: SVGSVGElement;

	function exportPNG() {
		if (!svgElement) return;

		// We need to fetch any external stylesheets/fonts or just hope they are rendered 
		// if they are standard. Since this is just SVG to Canvas.
		const svgData = new XMLSerializer().serializeToString(svgElement);
		const canvas = document.createElement('canvas');
		const ctx = canvas.getContext('2d');

		const width = parseInt(svgElement.getAttribute('width') || '1080');
		const height = parseInt(svgElement.getAttribute('height') || '1350');
		canvas.width = width;
		canvas.height = height;

		const img = new Image();
		img.onload = () => {
			if (ctx) {
				ctx.drawImage(img, 0, 0, width, height);
				URL.revokeObjectURL(img.src);
				const pngUrl = canvas.toDataURL('image/png');
				const downloadLink = document.createElement('a');
				downloadLink.href = pngUrl;
				downloadLink.download = 'match_post.png';
				document.body.appendChild(downloadLink);
				downloadLink.click();
				document.body.removeChild(downloadLink);
			}
		};

		const svgBlob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
		const url = URL.createObjectURL(svgBlob);
		img.src = url;
	}
</script>

<div class="mb-3">
	<button class="btn btn-primary" on:click={exportPNG}>Export as PNG</button>
</div>

